(x, y, t) => {
  const cx = 240, cy = 120;
  const sources = [
    [120 + Math.sin(t * 0.7) * 90, 60 + Math.cos(t * 0.5) * 40, 0.08, 2.0],
    [360 + Math.cos(t * 0.6) * 90, 60 + Math.sin(t * 0.8) * 40, 0.09, 1.8],
    [240 + Math.sin(t * 0.4 + 1) * 130, 180 + Math.cos(t * 0.6 + 2) * 70, 0.07, 2.2],
    [80 + Math.cos(t * 0.3) * 60, 160 + Math.sin(t * 0.5 + 3) * 80, 0.11, 1.5],
    [400 + Math.sin(t * 0.5 + 4) * 60, 140 + Math.cos(t * 0.4 + 1) * 80, 0.1, 1.9],
    [240 + Math.cos(t * 0.8 + 2) * 160, 50 + Math.sin(t * 0.3) * 30, 0.065, 2.5]
  ];
  let activator = 0, inhibitor = 0;
  for (let i = 0; i < sources.length; i++) {
    const [sx, sy, freq, spd] = sources[i];
    const d = Math.sqrt((x - sx) ** 2 + (y - sy) ** 2);
    const w = Math.sin(d * freq - t * spd) / (1 + d * 0.003);
    activator += w * (i < 3 ? 1 : 0.6);
    inhibitor += Math.sin(d * freq * 1.3 + t * spd * 0.7) * 0.5;
  }
  const dist = Math.sqrt((x - cx) ** 2 + (y - cy) ** 2);
  const ang = Math.atan2(y - cy, x - cx);
  const radW = Math.sin(dist * 0.035 - t * 1.2);
  const angW = Math.sin(ang * 8 + t * 0.3) * 0.4 + Math.sin(ang * 3 - t * 0.5) * 0.3;
  const spiral = Math.sin(dist * 0.02 + ang * 3 - t * 0.8);
  const warpX = x + Math.sin(y * 0.04 + t) * 8;
  const warpY = y + Math.cos(x * 0.04 - t * 0.7) * 8;
  const micro = Math.sin(warpX * 0.12 + t * 2) * Math.cos(warpY * 0.12 - t * 1.5) * 0.2;
  const actNorm = activator / 3.6, inhNorm = inhibitor / 3;
  let reaction = Math.tanh((actNorm - inhNorm * 0.7 + (radW + angW) * 0.3 + spiral * 0.15 + micro) * 2.2);
  const lap = (v) => {
    const s = 6;
    return (Math.sin((x+s)*0.05)*Math.sin(y*0.05) + Math.sin((x-s)*0.05)*Math.sin(y*0.05) +
            Math.sin(x*0.05)*Math.sin((y+s)*0.05) + Math.sin(x*0.05)*Math.sin((y-s)*0.05) - 4*v);
  };
  reaction += lap(Math.sin(x*0.05)*Math.sin(y*0.05)) * 0.15;
  reaction = Math.tanh(reaction * 1.8);
  const edge = 1 - Math.min(1, dist / 200);
  const vignette = Math.pow(edge, 0.6);
  const lum = 0.82 + Math.sin(reaction * Math.PI * 2) * 0.18;
  const v = reaction * 0.5 + 0.5;
  const pal = [
    [8, 15, 58], [15, 60, 110], [20, 120, 140], [60, 175, 150],
    [180, 200, 100], [230, 180, 60], [220, 120, 50], [180, 60, 70],
    [100, 30, 80], [40, 20, 90], [8, 15, 58]
  ];
  const idx = v * (pal.length - 1), i = Math.min(idx | 0, pal.length - 2), f = idx - i;
  return [
    Math.min(255, (pal[i][0] + (pal[i+1][0] - pal[i][0]) * f) * lum * vignette) | 0,
    Math.min(255, (pal[i][1] + (pal[i+1][1] - pal[i][1]) * f) * lum * vignette) | 0,
    Math.min(255, (pal[i][2] + (pal[i+1][2] - pal[i][2]) * f) * lum * vignette) | 0
  ];
}
